mat2 rot(float a) { float s = sin(a), c = cos(a); return mat2(c, -s, s, c); }
float sdTorus(vec3 p, vec2 t) {
  vec2 q = vec2(length(p.xz) - t.x, p.y);
  return length(q) - t.y;
}
float map(vec3 p) {
  p.yz = rot(0.5) * p.yz;
  vec3 p1 = p; p1.xz = rot(time * 0.5) * p1.xz;
  vec3 p2 = p; p2.xy = rot(-time * 0.7) * p2.xy;
  vec3 p3 = p; p3.yz = rot(time * 0.9) * p3.yz;
  float r1 = sdTorus(p1, vec2(1.4, 0.06));
  float r2 = sdTorus(p2, vec2(1.0, 0.05));
  float r3 = sdTorus(p3, vec2(0.6, 0.04));
  float core = length(p) - (0.28 + 0.05 * sin(time * 3.0));
  return min(min(r1, r2), min(r3, core));
}
shader_body {
  vec2 p = (uv - 0.5) * vec2(aspect.x, 1.0) * 2.0;
  vec3 ro = vec3(0.0, 0.0, -3.5);
  vec3 rd = normalize(vec3(p, 1.6));
  float t = 0.0;
  for (int i = 0; i < 48; i++) {
    float d = map(ro + rd * t);
    if (d < 0.003 || t > 8.0) break;
    t += d * 0.8;
  }
  vec3 col = vec3(0.03, 0.02, 0.01);
  if (t < 8.0) {
    vec3 pos = ro + rd * t;
    vec2 e = vec2(0.004, 0.0);
    vec3 n = normalize(vec3(
      map(pos + e.xyy) - map(pos - e.xyy),
      map(pos + e.yxy) - map(pos - e.yxy),
      map(pos + e.yyx) - map(pos - e.yyx)
    ));
    vec3 l = normalize(vec3(1.5, 2.0, -2.0));
    float diff = max(dot(n, l), 0.0);
    float spec = pow(max(dot(reflect(-l, n), -rd), 0.0), 32.0);
    col = vec3(0.1, 0.07, 0.02) + diff * vec3(0.9, 0.7, 0.2) + spec * vec3(1.0, 0.9, 0.7);
  }
  ret = col;
}
